import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const variants = [
  { id: "variant-a", ordinal: 1, source: "inputs/a.txt" },
  { id: "variant-b", ordinal: 2, source: "inputs/b.txt" },
];

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const outputPath = resolve(root, "data/artifacts.json");

if (process.argv.includes("--help") || process.argv.includes("-h")) {
  console.log("Usage: node tools/materialize.mjs\n\nMaterialize data/artifacts.json from the configured input variants.");
  process.exit(0);
}

if (process.argv.length > 2) {
  throw new Error(`Unknown argument: ${process.argv[2]}`);
}

const artifacts = [];

for (const variant of variants) {
  const bytes = await readFile(resolve(root, variant.source));
  artifacts.push({
    ...variant,
    byteLength: bytes.length,
    sha256: createHash("sha256").update(bytes).digest("hex").toUpperCase(),
  });
}

artifacts.sort((left, right) => left.ordinal - right.ordinal);

const output = `${JSON.stringify(artifacts, null, 2)}\n`;
await mkdir(dirname(outputPath), { recursive: true });
await writeFile(outputPath, output, "utf8");

const writtenOutput = await readFile(outputPath, "utf8");
if (writtenOutput !== output) {
  throw new Error("data/artifacts.json did not match the materialized output");
}

console.log(`Materialized ${artifacts.length} artifacts to data/artifacts.json`);

